"""Explain dummy metadata, page orders, internal contracts and page links."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1741': ('실제 검사표가 없을 때 읽기용 빈 표와 쓰기용 연습장을 따로 둬요. 연습장에 무언가 써도 읽기용 빈 표까지 바뀌면 안 되기 때문이에요.', '실제 데이터와 대체 검사 정보를 구별하고 읽기·쓰기 공간을 나누는 이유를 이해합니다.', '실제 데이터42와 dummy shadow0을 따로 적고,store용 표와 load용 표 사이에는 쓰기 전달 화살표가 없다고 표시하세요.', ['kmsan_get_shadow_origin_ptr는 데이터 주소와 길이,store 여부를 받아 검사 정보 주소 두 개를 돌려줘요. shadow는 준비 상태,origin은 원인 정보예요. store는 쓰기 쪽인지 나타내고 거짓이면 읽기 쪽이에요. 반환되는 주소는 실제 데이터 주소와 역할이 달라요.', 'KMSAN이 비활성 상태이거나 대상 shadow를 찾지 못하면 return_dummy로 가요. dummy는 실제 대상의 검사 정보 대신 사용할 대체 공간이라는 뜻이에요. 정상적으로 추적되는 경로에서는 실제 shadow와 origin 주소를 돌려줘요.', '대체 경로에서 store가 참이면 두 반환 포인터를 dummy_store_page로 정해요. store가 거짓이면 둘 다 dummy_load_page로 정해요. 두 페이지는 별도 배열이므로 쓰기용 공간에 기록한 값이 읽기용 공간을 바꾸지 않아요.', '주석의 load가0이라는 말은 검사 정보 읽기의 결과예요. shadow0은 준비된 상태로 해석돼요. 예를 들어 실제 데이터가42여도 대체 shadow는0일 수 있어요. 이 getter가 실제 데이터42를0으로 바꾸는 코드는 아니에요.', '왜 하나의 공간을 같이 쓰지 않을까요? 쓰기 계측이 그 공간에 미준비 표시를 남기면 뒤의 관계없는 읽기까지 오염된 검사 상태를 볼 수 있기 때문이에요. 읽기용0 공간을 분리해 이 영향을 피하는 구조예요.', '대체 페이지도 크기가 한정돼 있어요. 함수는 size>PAGE_SIZE이면 경고해요. 이 경고가 size를 자동으로 줄이는 코드는 아니므로 아무 큰 접근도 대체 공간으로 안전하게 처리된다고 생각하면 안 돼요. 길이와 접근의 호출 조건을 지켜야 해요.'], [('dummy load의0은 실제 데이터 값도0으로 바꾼다는 뜻인가요?', ['네. 미추적 데이터는 전부0이 돼요', '아니요. 읽어 오는 검사 정보가0이라는 뜻이에요'], '정답은 두 번째예요. getter는 shadow와 origin 포인터를 돌려줘요. 실제 데이터42와 그 값의 준비 상태를 나타내는 shadow0은 함께 존재할 수 있어요.'), ('읽기와 쓰기용 dummy는 같은 한 페이지인가요?', ['아니요. 서로 다른 두 페이지예요', '네. 쓰기마다 다음 읽기의 검사 상태를 바꿔요'], '정답은 첫 번째예요. dummy_store_page와 dummy_load_page를 나눠요. 대체 공간에 쓴 검사 표시가 관계없는 읽기 상태를 바꾸지 않게 하려는 구조예요.')]), 'os1742': ('물건마다 준비 상태표와 원인표를 연결해요. 검사표 자체에 또 같은 검사표를 끝없이 달지 않도록, 검사표 보관 공간은 별도로 표시해요.', '할당 order에서 페이지 수를 계산하고 데이터와 검사 페이지를 연결합니다.', 'order0·1·2를 페이지1·2·4개로 바꾸고 data[i]에서 shadow[i]와 origin[i]로 두 화살표를 그리세요.', ['kmsan_setup_meta는 데이터 페이지와 그에 대응하는 shadow·origin 페이지를 연결하는 함수예요. page는 커널의 페이지 정보 구조체를 가리켜요. shadow와 origin은 실제 데이터와 별도로 검사에 쓰는 저장 공간이에요.', 'order는 페이지 개수 자체가 아니에요. 반복 횟수는1<<order,즉2의 order제곱이에요. order0은1페이지,order1은2페이지,order2는4페이지예요. order2라고2페이지만 연결하면 원래 묶음의 절반을 빠뜨리게 돼요.', '반복문의 i는0부터 페이지 수보다 작을 때까지 움직여요. order2에서는0·1·2·3 네 번이에요. 각 단계에서 데이터 page[i]와 shadow[i],origin[i]를 같은 번호끼리 연결해요.', '먼저 shadow[i]와 origin[i]에 set_no_shadow_origin_page를 호출해요. 이 함수는 해당 페이지의 두 검사 정보 연결을NULL로 놓아요. 검사표 자체에 다시 검사표를 연결하는 재귀적인 추적을 피하려는 구분이에요.', '그 다음 데이터 page[i]의 shadow 연결에는 &shadow[i],origin 연결에는 &origin[i]를 저장해요. &는 해당 페이지 구조체의 주소를 얻는 기호예요. 실제 데이터 페이지와 두 검사 페이지가 한 주소로 합쳐지는 것이 아니라 서로 연결되는 것이에요.', '이 함수는 전달받은 페이지들을 연결하는 단계예요. 여기서 부팅 시 할당 전체나 모든 페이지 내용을 준비한다고 말하면 안 돼요. 초기 범위의 메타데이터 할당을 위한 별도 선언도 있지만 그 구현과 이 연결 작업의 역할은 구별해야 해요.'], [('order=2이면 이 연결 반복은 몇 페이지를 다루나요?', ['2페이지예요', '1<<2=4페이지예요'], '정답은 두 번째예요. order는 페이지 개수를2의 거듭제곱으로 나타내는 값이에요. 반복 번호는0·1·2·3으로 네 개예요.'), ('shadow와 origin 페이지에도 검사 페이지를 끝없이 다시 연결하나요?', ['아니요. 그 페이지들의 검사 연결은없음으로 표시해요', '네. 같은 메타데이터를 무한히 생성해요'], '정답은 첫 번째예요. 두 검사 페이지에 set_no_shadow_origin_page를 먼저 호출해요. 데이터 추적용 공간과 실제 추적 대상의 역할을 구별하는 처리예요.')]), 'os1743': ('안내 직원이 입장 조건을 확인하고 안쪽 직원은 짧은 일을 맡을 수 있어요. 하지만 안쪽 직원이라는 이름만으로 아무 물건이나 받아도 되는 것은 아니에요.', '내부 도우미의 설계 의도와 주소·길이 계약을 구별합니다.', '공개hook→internal도우미→metadata조회 화살표에 각각 진입조건·상태처리·주소조회 역할을 적으세요.', ['internal은 내부에서 사용하는 도우미라는 뜻이에요. KMSAN의 내부 함수들은 검사 상태 표시,복사,원인 연결,작업 상태 준비 같은 역할을 나눠 맡아요. 함수 이름은 그 역할을 알려 주지만 모든 사용 조건을 대신하지는 않아요.', '헤더 주석은 kmsan_internal_ 함수가 아주 단순하고 kmsan_in_runtime 검사를 요구하지 않도록 설계되어야 한다고 설명해요. in_runtime은 이미 검사 코드 안인지 판단해 재귀 진입을 피하는 데 쓰는 검사예요.', '공개hook과 내부 도우미의 책임을 나눠 읽어야 해요. 모든 바이트 처리마다 똑같은 진입 검사를 무조건 붙인다는 뜻이 아니에요. 원문의 non-blocking 함수 설명도 무조건 빠져나가서 초기화 사건을 놓치는 일을 줄이려는 고려를 말해요.', '그렇다고 internal이라는 이름이 잘못된 주소를 고쳐 주지는 않아요. 예를 들어 검사 정보를 조회했는데 없을 수 있고,연속이어야 할 범위가 끊겨 있을 수 있어요. 각 함수가 요구하는 주소·길이·메타데이터 배치 조건은 여전히 지켜야 해요.', '앞에서 본 set_shadow_origin은 연속성 경고와 shadow 조회를 하고,shadow가 없을 때 checked에 따라 진단을 달리했어요. 이런 구체적인 코드가 실제 처리 범위를 보여 줘요. 내부 함수라는 이름만 보고 항상 검사 정보가 있다고 가정하면 안 돼요.', '또 주석의 설계 의도를 모든 호출 경로의 잠금·대기 동작을 완전히 증명한 결과로 읽지 마세요. 호출하는 함수와 호출되는 함수를 함께 확인해야 해요. 이번 수업은 역할 분담을 배우는 것이며 기존 함수에 임의로 guard를 더 넣는 구현 변경이 아니에요.'], [('헤더는 internal 함수마다 항상 in_runtime 검사를 하라고 하나요?', ['네. 모든 바이트마다 반드시 반복해요', '아니요. 단순하게 설계해 그 검사를 요구하지 않도록 설명해요'], '정답은 두 번째예요. 외부 진입과 내부 상태 처리의 책임을 나누어 읽어야 해요. 모든 helper에 똑같은 guard가 있어야 한다는 설명이 아니에요.'), ('internal이라는 이름이면 어떤 주소·길이도 유효해지나요?', ['아니요. 함수별 주소·길이·배치 조건이 필요해요', '네. 잘못된 포인터도 자동 보정돼요'], '정답은 첫 번째예요. 이름은 역할을 나타내요. 메타데이터 조회와 연속성 같은 실제 전제는 구현과 호출 경로에서 확인해야 해요.')]), 'os1744': ('물건 카드에 준비 상태표 주소와 원인표 주소를 함께 적어요. 둘 중 하나가 비어 있으면 두 검사표가 모두 연결됐다고 할 수 없어요.', '두 메타데이터 페이지 연결과 주소 조회 대상을 구별합니다.', '데이터페이지D→shadow페이지S, D→origin페이지O를 그리세요. S만있음·O만있음·둘다있음의 조건값을 거짓·거짓·참으로 적으세요.', ['데이터 page에는 kmsan_shadow와 kmsan_origin이라는 연결이 있어요. 각각 준비 상태표 페이지와 원인 정보 페이지를 가리켜요. shadow_page_for와 origin_page_for 매크로는 이 연결 필드를 읽는 짧은 이름이에요.', 'page_has_metadata의 식은 shadow_page_for(page) && origin_page_for(page)예요. &&는 두 조건이 모두 맞아야 한다는 뜻이에요. 포인터가NULL이면 연결이 없는 것으로 보고,둘 다 있어야 참이에요.', '따라서 shadow만 있거나 origin만 있으면 이 함수는 거짓이에요. 둘 다 있어야 참이지만 이것만으로 연결된 메모리의 모든 수명과 접근 안전성을 검사했다고 말할 수는 없어요. 이 함수가 직접 확인하는 것은 두 연결의 존재예요.', 'shadow_ptr_for는 page_address(shadow_page_for(page))를 반환해요. 먼저 연결된 shadow 페이지를 고른 다음 그 페이지의 메모리 주소를 얻어요. 실제 데이터 페이지 주소를 그대로 돌려주는 식과 달라요. origin_ptr_for도 원인 페이지를 같은 방식으로 골라요.', '예를 들어 데이터D의 shadow연결이S라면 shadow_ptr_for(D)는S의 주소를 구해요. D와S는 다른 역할의 공간이에요. 준비 상태를 고치려다 실제 데이터D를 덮어쓰는 것처럼 이해하면 안 돼요.', 'set_no_shadow_origin_page는 두 연결 필드를NULL로 바꿔요. 이 짧은 함수에 페이지를 해제하거나 내용을0으로 채우는 동작은 없어요. 연결 표시,메모리 주소 조회,실제 저장 공간의 수명 관리를 서로 구별해서 읽으세요.'], [('shadow만 있고 origin이 없으면 page_has_metadata는 참인가요?', ['네. shadow하나면 충분해요', '아니요. 두 연결이 모두 있어야 해요'], '정답은 두 번째예요. &&로 두 포인터를 확인해요. 준비 상태표와 원인표 중 하나가 없는 상태를 둘 다 연결된 상태로 보지 않아요.'), ('shadow_ptr_for는 실제 데이터 페이지의 주소를 반환하나요?', ['아니요. 연결된 shadow페이지의 주소예요', '네. 언제나 원래 데이터 주소예요'], '정답은 첫 번째예요. page_address에 넣는 것은shadow_page_for(page)의 결과예요. 데이터 페이지에서 검사 페이지로 먼저 이동한 뒤 그 주소를 얻어요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_431.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
